from datetime import date

class Solution(object):
    def daysBetweenDates(self, date1, date2):
        y1, m1, d1 = map(int, date1.split('-'))
        y2, m2, d2 = map(int, date2.split('-'))
        dt1 = date(y1, m1, d1)
        dt2 = date(y2, m2, d2)
        return abs((dt2 - dt1).days)
